function updateCombat(dt){const surface=state.phase==='surface';enemyClock-=dt;hazardClock-=dt;if(!surface){const candidates=state.match.teams.slice(1).filter(t=>!t.eliminated&&['outbound','return'].includes(t.phase)&&!enemies.some(e=>e.teamId===t.id));if(enemyClock<=0&&candidates.length){enemyClock=6/state.route.hazard;const t=candidates[0],m=ship.clone(true);m.scale.setScalar(.45);m.position.set((Math.random()-.5)*34,2+Math.random()*6,-90);m.traverse(o=>{if(o.isMesh&&o.material?.emissiveIntensity>0)o.material=material(t.color,0,.3,true);});scene.add(m);enemies.push({mesh:m,hp:t.hull,teamId:t.id,teamColor:t.color,cd:2});}if(hazardClock<=0){hazardClock=4.5/state.route.hazard;const m=mesh(new THREE.IcosahedronGeometry((.8+Math.random()*.8)*SK*1.5,0),material('#8f7c7e'));m.position.set((Math.random()-.5)*34,1+Math.random()*4,-150);hazards.push({mesh:m,speed:(6+Math.random()*3)*2.6});}for(const e of[...enemies]){if(state.match.teams[e.teamId].eliminated){e.mesh.removeFromParent();enemies=enemies.filter(n=>n!==e);continue;}e.mesh.position.z+=dt*(e.mesh.position.z<-25?9:2.4);e.mesh.position.x+=Math.sin(time+e.teamId)*dt*.5;e.cd-=dt;if(e.cd<=0&&state.decoy<=0){e.cd=2.8;hostilePulse(e.mesh.position,ship.position.clone().add(new THREE.Vector3(0,SK,0)),e.teamColor,6);}if(e.mesh.position.z>25){e.mesh.removeFromParent();enemies=enemies.filter(n=>n!==e);}}for(let i=hazards.length-1;i>=0;i--){const h=hazards[i];h.mesh.position.z+=dt*h.speed;h.mesh.rotation.x+=dt*.3;if(h.mesh.position.distanceTo(ship.position)<2.4*SK){hit(9);sparks(h.mesh.position,'#edba82',8);h.mesh.position.z=40;}if(h.mesh.position.z>32){h.mesh.removeFromParent();h.mesh.geometry.dispose();hazards.splice(i,1);}}}
else for(const t of state.match.teams.slice(1)){if(t.eliminated||t.planet!=='B'||t.phase!=='surface')continue;rivalShotClock[t.id]-=dt;const v=world.rivalShips.find(v=>v.team.id===t.id),from=v.crew[2].group.getWorldPosition(new THREE.Vector3()).add(new THREE.Vector3(0,1.1,0)),to=world.actors[3].group.position.clone().add(new THREE.Vector3(0,1.1,0));if(from.distanceTo(to)<36&&rivalShotClock[t.id]<=0){rivalShotClock[t.id]=1.4;hostilePulse(from,to,t.color,6);}}
for(let i=bullets.length-1;i>=0;i--){const b=bullets[i],prev=b.mesh.position.clone();b.mesh.position.addScaledVector(b.v,dt);b.life-=dt;const seg=new THREE.Line3(prev,b.mesh.position);let used=false,verifiedHit=false;const blockers=surface?pdf.cover:hazards.map(h=>({position:h.mesh.position,radius:1.1}));for(const rock of blockers){seg.closestPointToPoint(rock.position,true,tmp);if(tmp.distanceTo(rock.position)<rock.radius){used=true;break;}}
if(!used&&b.hostile){if(surface){for(const role of[...new Set([state.selected,3])]){const p=world.actors[role].group.position.clone().add(new THREE.Vector3(0,1.1,0));seg.closestPointToPoint(p,true,tmp);if(tmp.distanceTo(p)<.65){hit(b.damage,role);used=true;break;}}}else{const p=ship.position.clone().add(new THREE.Vector3(0,SK,0));seg.closestPointToPoint(p,true,tmp);if(tmp.distanceTo(p)<1.7){hit(b.damage);used=true;}}}
else if(!used&&!b.hostile){if(surface){for(const t of state.match.teams.slice(1)){if(t.eliminated||t.planet!=='B')continue;const person=new THREE.Vector3(...t.botPosition).add(new THREE.Vector3(0,1.1,0));seg.closestPointToPoint(person,true,tmp);if(tmp.distanceTo(person)<.8){dropFlag(state.match,t.id,3,t.botPosition,'B');t.stun=1.2;t.fieldHealth=(t.fieldHealth??100)-b.damage;if(t.fieldHealth<=0){t.botPosition=[...LANDING_BAYS[t.id]];t.fieldHealth=100;t.stun=4;}sparks(person,t.color,3);used=true;verifiedHit=true;break;}const hull=new THREE.Vector3(...t.position).add(new THREE.Vector3(0,1.5,0));seg.closestPointToPoint(hull,true,tmp);if(tmp.distanceTo(hull)<2){damageCrew(state.match,t.id,b.damage*4,t.position,'B');used=true;verifiedHit=true;break;}}}else for(const e of[...enemies]){seg.closestPointToPoint(e.mesh.position,true,tmp);if(tmp.distanceTo(e.mesh.position)<1.5){damageEnemy(e,b.damage);used=true;verifiedHit=true;break;}}}
if(verifiedHit&&b.humanShot){recordCrewAction(state,'combatHits');pulseHitFeedback();}if(used||b.life<=0){b.mesh.removeFromParent();bullets.splice(i,1);}}}
function hostilePulse(from,to,color,damage){const v=to.clone().sub(from).normalize().multiplyScalar(13),m=sphere(.1,color,scene,from.x,from.y,from.z,6);m.material=material(color,0,.3,true);bullets.push({mesh:m,v,hostile:true,damage,life:4});}
let lastObjective=null;function objectiveWaypoint(){lastObjective=null;let point,label;const role=state.selected,pos=world.actors[role].group.position;if(state.phase==='assembly'){const p=state.parts.find(p=>p.owner===role&&p.stage!=='secured'),v=world.partVisuals.find(v=>v.part===p);if(v){point=p.stage==='shelf'?v.shelf.position:p.stage==='positioned'?v.bolts[p.bolts.findIndex(b=>b<1)].position:new THREE.Vector3(...p.position);label=p.stage==='shelf'?'BUY & CARRY '+p.name:p.stage==='positioned'?'FASTEN '+p.name:'MOUNT '+p.name;}}else if(state.phase==='outfit'){if(state.carry[role]?.startsWith('cargo:')){point=new THREE.Vector3(0,0,STOW_Z);label='STOW SUPPLIES';}else{const c=world.cargoVisuals.find(v=>!v.cargo.stowed&&v.cargo.owner===role);if(c){point=c.group.position;label='LOAD '+c.cargo.name;}else if(state.cargo.every(c=>c.stowed)){const c=world.checks.find(c=>c.role===role&&state.checks[c.id]<1);if(c){point=c.group.getWorldPosition(new THREE.Vector3());label=c.id.toUpperCase()+' TEST';}}}}else if(state.phase==='surface'){const c=flagCounts(state.match,0);if(c.carried||c.onboard>=state.cargoCapacity){point=ship.position;label=c.carried?'LOAD SCIENCE FLAG':'RETURN TO A';}else{const available=state.match.flags.filter(f=>f.planet==='B'&&['site','ground'].includes(f.state));available.sort((a,b)=>pos.distanceTo(new THREE.Vector3(...a.position))-pos.distanceTo(new THREE.Vector3(...b.position)));const f=available[0];if(f){point=new THREE.Vector3(...f.position);label=f.state==='ground'?'RECOVER SCIENCE FLAG':['SCAN','STABILIZE','EXTRACT'][f.stage]+' SAMPLE';}}}else if(state.phase==='delivery'){point=pdf.receiver.position;label='DELIVER SCIENCE TO PLANET A';}else if(state.phase==='flight'&&role===1){const c=world.consoles.find(c=>c.id===(state.co2>1500?'scrubber':state.temperature>65?'coolant':'reactor'));point=c.group.getWorldPosition(new THREE.Vector3());label=c.label;}if(!point)return '';lastObjective={x:point.x,z:point.z,label};const d=pos.distanceTo(point),v=point.clone().add(new THREE.Vector3(0,.5,0)).project(camera);return `<div class="ce-waypoint" style="left:${clamp(v.x*.5+.5,.24,.76)*100}%;top:${clamp(-v.y*.5+.5,.25,.66)*100}%"><span>◇</span><b>${label}</b><small>${fmt(d,1)} M · B TO FOCUS</small></div>`;}
function outfitHtml(){const b=cargoBalance(state);return `<div class="ce-machine"><b>CARGO BALANCE: ${b.status}</b><small>${b.mass} kg stowed · offset ${b.offset.toFixed(2)}${b.ok?'':' · move items to the other side'}</small></div>`+outfitTasks(state).map(t=>`<div class="ce-task ${t.done?'done':''}"><i>${t.done?'✓':'◎'}</i><div><b>${SPECIALISTS[t.role].role}</b><small>${t.text}</small></div></div>`).join('');}
function alertsHtml(){const a=roleAlerts(state);return `<div class="ce-alerts">${a.map(x=>`<div class="ce-alert ${x.level}">${x.text}</div>`).join('')}<div class="ce-alert info">NEXT SCHEDULED FAULT IN ${nextFaultIn(state)}s</div></div>`;}
function machinePanelHtml(){const a=state.autoBuild||{t:0,priority:'standard'};if(!a.enabled){const done=state.parts.filter(p=>p.stage==='secured').length;return `<div class="ce-machine"><b>HANDS-ON CONSTRUCTION · ${done}/12</b><small>Build your own role's modules. Teammates complete their assigned work.</small><button type="button" class="ce-mini" data-action="build-assist">LET MACHINES FINISH THE BUILD ↗</button></div>${guideHtml(state.selected)}${state.parts.map(p=>`<div class="ce-task ${p.stage==='secured'?'done':''}"><i>${p.stage==='secured'?'✓':'◇'}</i><div><b>${p.name}</b><small>${SPECIALISTS[p.owner].name} · ${p.stage.toUpperCase()}</small></div></div>`).join('')}`;}const pct=Math.min(100,a.t/AUTO_BUILD_SECONDS*100),left=Math.max(0,Math.ceil(AUTO_BUILD_SECONDS-a.t)),done=state.parts.filter(p=>p.stage==='secured').length;return `<div class="ce-machine"><b>ASSEMBLY MACHINES / ${done}/12 SECURED</b><div class="ce-machine-bar"><em style="width:${pct}%"></em></div><small>${left}s remaining</small><div class="ce-machine-prio">${Object.entries(BUILD_PRIORITIES).map(([k,v])=>`<button class="ce-mini ${a.priority===k?'on':''}" data-action="priority" data-mode="${k}" ${a.t>1?'disabled':''} title="${v.note}">${v.label}</button>`).join('')}</div></div>`+buildOrder(state).map(p=>`<div class="ce-task ${p.stage==='secured'?'done':''}"><i>${p.stage==='secured'?'✓':p.stage==='shelf'?'◇':'⚙'}</i><div><b>${p.name}</b><small>${machineStatus(p)}</small></div></div>`).join('');}
const PHASE_STEPS=[['assembly','BUILD'],['outfit','OUTFIT'],['route','ROUTE'],['flight','FLIGHT'],['surface','PLANET B'],['delivery','DELIVER']];
function missionBoardHtml(){const summary=missionSummary(state);const active=summary.active.slice(0,missionExpanded?summary.total:2);const completed=missionExpanded?summary.cards.filter(c=>c.done):[];const rows=[...active,...completed];return `<section class="ag-mission-board" aria-label="Mission contracts"><div class="ag-mission-top"><b>MISSION CONTRACTS · ${summary.done}/${summary.total}</b><button type="button" class="ce-mini" data-action="mission-board">${missionExpanded?'LESS':'ALL'} [J]</button></div><div class="ag-mission-tally">EARNED IF MATCH ENDS: +${summary.xp} XP · +${summary.credits} CR</div>${rows.map(card=>`<article class="ag-contract ${card.done?'done':''}"><span>${card.done?'✓':'◈'} ${card.role}</span><strong>${card.name}</strong><small>${card.value}/${card.max} · +${card.xp} XP</small>${missionExpanded?`<p>${card.detail}</p>`:''}<i><em style="width:${card.value/card.max*100}%"></em></i></article>`).join('')||'<small>All mission contracts complete.</small>'}<small class="ag-mission-foot">Bonuses are awarded at debrief, not during a match.</small></section>`;}
function trackerHtml(){const cur=state.phase==='spectator'?'delivery':state.phase,idx=Math.max(0,PHASE_STEPS.findIndex(s=>s[0]===cur)),left=Math.max(0,Math.round(state.match.limit-state.match.time)),mm=String(Math.floor(left/60)).padStart(2,'0'),ss=String(left%60).padStart(2,'0');return `<div class="hud-tracker">${PHASE_STEPS.map((s,i)=>`<span class="${i<idx?'done':i===idx?'now':''}">${s[1]}</span>`).join('<i></i>')}<b>${mm}:${ss}</b></div>`;}
function vitalsHtml(){if(!['flight','delivery'].includes(state.phase))return '';const row=(l,v,max,warn)=>{const p=clamp(v/max*100,0,100);return `<div class="hud-vital ${p<warn?'low':''}"><span>${l}</span><i><em style="width:${p}%"></em></i><b>${Math.round(p)}%</b></div>`;};return `<div class="hud-vitals">${row('HULL',state.hull,100,30)}${row('POWER',state.power,state.powerCapacity,20)}${row('FUEL',state.propellant,80,25)}${row('O₂',5000-state.co2,5000,35)}</div>`;}
function updateHUD(){const role=state.selected,r=SPECIALISTS[role],c=flagCounts(state.match,0),phase=state.phase,t=state.match.teams[0],secured=state.parts.filter(p=>p.stage==='secured').length,minutes=Math.floor(state.match.time/60),seconds=Math.floor(state.match.time%60);let title=phase==='assembly'?'BUILD BEFORE THEY LAUNCH.':phase==='outfit'?'EVERY MODULE HAS A COST.':phase==='surface'?'CAPTURE THE FRONTIER.':phase==='delivery'?'BRING IT HOME.':phase==='spectator'?t.eliminated?'CREW ELIMINATED':'SCIENCE DELIVERED':state.flightLeg==='return'?'THE FLAGS ARE NOT HOME YET.':'FLY. DEFEND. KEEP IT ALIVE.';
let tasks=phase==='assembly'?machinePanelHtml():phase==='outfit'?outfitHtml()+state.cargo.map(c=>`<div class="ce-task ${c.stowed?'done':''}"><i>${c.stowed?'✓':'□'}</i><div><b>${c.name}</b></div></div>`).join('')+Object.entries(state.checks).map(([id,p])=>`<div class="ce-task ${p>=1?'done':''}"><i>${p>=1?'✓':'◎'}</i><div><b>${id.toUpperCase()} TEST ${fmt(p*100)}%</b><small>${SPECIALISTS[id==='engine'?0:1].role}</small></div></div>`).join(''):phase==='surface'?`<div class="ag-extraction-steps"><b>SCAN</b><span>→</span><b>STABILIZE</b><span>→</span><b>EXTRACT</b></div><p>Raider: aim at a site and HOLD E to scan. LMB fires, RMB aims, MMB throws a grenade. E loads at the ship or recovers flags. G drops your flag.</p><div class="ag-cargo-state"><b>${c.carried?'CARRYING SCIENCE FLAG':c.onboard>=state.cargoCapacity?'CARGO RACKS FULL':'FLAGS AT SITES: '+c.sites}</b><span>ONBOARD ${c.onboard}/${state.cargoCapacity} · DELIVERED ${c.delivered}</span></div><div class="ag-cargo-state"><b>RAID RISK ON RETURN: ${raidOdds(state,c.onboard)}%</b><span>${c.onboard<4?'Land now with '+c.onboard+', or wait for more flags (risk rises 4% per flag).':'Cargo racks full: land now.'}</span></div><button class="ce-primary" data-action="return" ${c.onboard===0||c.carried?'disabled':''}>RETURN TO A [N] ↗</button>`:phase==='delivery'?`<p>Walk to the receiving station. Press E to transfer each flag. Loading on Planet B did not score.</p><div class="ag-cargo-state"><b>${c.onboard} FLAGS AWAIT DELIVERY</b><span>${c.delivered}/12 FLAGS DELIVERED</span></div>`:phase==='spectator'?`<p>${t.eliminated?'All four orange crew members are eliminated. Flags aboard became recoverable cargo.':'Your flags have reached home. The other crews are still competing.'}</p><button class="ce-secondary" data-action="next-team">SPECTATE NEXT CREW</button><button class="ce-secondary" data-action="free-cam">${spectatorFree?'FOLLOW CREW':'FREE CAMERA (WASD)'}</button><button class="ce-secondary" data-screen="select">NEW MATCH / REJOIN</button><button class="ce-secondary" data-action="fast-spectate">${spectatorSpeed===1?'SPEED UP RESULTS ×10':'NORMAL SPEED'}</button>`:`<p>${r.job}</p><div class="ce-task"><i>◎</i><div><b>${r.inside}</b><small>${role===0?'Maneuver around rocks. Barbara covers the ship.':role===1?'LMB services consoles; wheel adjusts reactor output.':role===2?'LMB operates the dorsal turret.':'Monitor cargo. X toggles exterior repair work.'}</small></div></div>`;
const hit=lastHit,carried=state.carry[role],p=state.parts.find(p=>p.id===carried),flag=hit?.type==='science'?state.match.flags[hit.id]:null;let prompt=phase==='surface'?c.carried?'CARRY → SHIP · E LOAD · G DROP':flag&&flag.state==='site'?'HOLD E · '+['SCAN','STABILIZE','EXTRACT'][flag.stage]+' '+fmt(flag.progress*100)+'%':'B FOCUS SAMPLE · HOLD E SCAN · E RECOVER':phase==='delivery'?'E TRANSFER FLAG TO RECEIVING STATION':hit?.type==='bolt'?'LMB HOLD · FASTEN '+(hit.bolt+1)+'/3':hit?.type==='console'?'LMB SERVICE · '+hit.id.toUpperCase():hit?.type==='test'?'LMB TEST · WHEEL CALIBRATES SETPOINT':hit?.type==='panel'?'E REMOVE · LMB REPAIR':carried?carried.startsWith('cargo:')?'E STOW IN AFT CARGO BAY':'WHEEL / R ROTATE '+state.rotation[role]*90+'° → '+p.angle*90+'° · CLICK / E MOUNT':phase==='assembly'?'LOOK AT A PART · CLICK OR E TO PICK UP':'E BUY / CARRY / INTERACT';
const preservedJobScroll=hud.querySelector('.ce-job-panel')?.scrollTop||0;hud.innerHTML=`<div class="ce-flight-header"><a class="ce-logo" href="#">APOG<span>EX</span><i>OFFLINE / 1 PLAYER + 15 BOTS</i></a><div class="ce-phase-pill">${state.flightLeg==='return'&&phase==='flight'?'RETURN TO A':phase==='surface'?'PLANET B / SCIENCE EXTRACTION':phase==='delivery'?'PLANET A / DELIVERY':phase==='assembly'?'PLANET A / BUILD TIME '+String(minutes).padStart(2,'0')+':'+String(seconds).padStart(2,'0'):'FOUR CREWS. ONE FRONTIER.'}</div><div><button data-action="telemetry" class="ce-mini">SYSTEMS [T]</button><button data-action="view" class="ce-mini">${state.views[role]==='first'?'FPV':'TPP'} [V]</button><button data-action="pause" class="ce-mini">MENU</button></div></div><div class="ce-mission-caption"><small>▲ ORANGE / HUMAN ${r.name} / ${r.role}</small><h2>${title}</h2><p>${phase==='assembly'?secured+'/12 MODULES · CREDITS '+state.credits.toLocaleString():phase==='flight'?'HULL '+fmt(state.hull*20)+'/2,000 · RETURN FUEL: '+(state.propellant>=(state.route?.returnReserve||0)?'SAFE':'LOW'):c.onboard+' FLAGS ONBOARD · '+c.delivered+' DELIVERED'}</p></div><aside class="ce-job-panel"><div class="ce-overline">${r.name} / ${r.role}</div>${tasks}${missionBoardHtml()}</aside>${phase==='flight'?alertsHtml():''}${trackerHtml()}${vitalsHtml()}${phase!=='spectator'?crewBarHtml():''}${state.cutaway?'<div class="ag-cutaway-key">FUEL · POWER · LIFE SUPPORT · CARGO · WEAPONS · RETURN MARGIN<br><small>X RETURNS TO CREW VIEW</small></div>':''}<div class="ag-score-strip"><div><span>FLAGS AT SITES</span><b>${c.sites}</b></div><div><span>FLAGS ONBOARD</span><b>${c.onboard}</b></div><div><span>DELIVERED</span><b>${c.delivered}</b></div></div><aside class="ce-race-board">${state.match.teams.map(t=>`<div style="--team:${t.color}"><span><i></i>${t.symbol} ${t.name}</span><b>${t.delivered} <small>DELIVERED</small></b><small class="ag-team-phase">${t.eliminated?'ELIMINATED':t.phase.toUpperCase()+(phase==='assembly'?' '+Math.round(t.progress/.25*100)+'%':'')}</small></div>`).join('')}</aside>${telemetry||role===1?`<aside class="ce-system-panel"><div class="ce-overline">SHIP SYSTEMS / T COLLAPSES</div>${[['HULL',state.hull*20,2000,'HP'],['POWER',state.power,6,'kWh'],['TEMPERATURE',state.temperature,100,'°C'],['CABIN',state.pressure,101.3,'kPa'],['CO₂',state.co2,5000,'ppm'],['FUEL',state.propellant,80,'kg'],['CARGO',c.onboard,state.cargoCapacity,'flags']].map(([label,v,max,u])=>`<div class="ce-system"><span>${label}</span><b>${fmt(v,v<20?1:0)} <small>${u}</small></b><i><em style="width:${clamp(v/max*100,0,100)}%"></em></i></div>`).join('')}<div class="ce-fault ${state.fault?'bad':''}">${state.fault?'POWER / SYSTEM FAULT: '+state.fault.toUpperCase()+(FAULT_REPAIR[state.fault]?' · PRESS K TO REPAIR BY HAND':''):'SYSTEMS NOMINAL'}</div></aside>`:''}${phase==='flight'&&state.fault?`<div class="ag-fault-alert" role="alert" data-fault="${state.fault}"><b>⚠ ${({reactor:'REACTOR POWER',power:'POWER',scrubber:'CO₂ SCRUBBER',cooling:'COOLING'})[state.fault]||state.fault.toUpperCase()} FAULT</b><span>${FAULT_REPAIR[state.fault]?'Press K to repair it by hand':'The engineer repairs it at the thermal console'}</span></div>`:''}${phase==='flight'&&showInset&&quality!=='low'?'<div id="ag-interior-inset"><span>INTERIOR / CREW STATIONS [I]</span></div>':''}${phase!=='spectator'?objectiveWaypoint()+'<div class="ce-crosshair"><i></i><i></i></div>':''}<div class="ce-context">${phase==='spectator'?'SPECTATE / '+state.match.teams[spectatorTeam].name:prompt}</div>${selectedCheck&&phase==='outfit'?`<div class="ce-calibration"><span>${selectedCheck.toUpperCase()} · ${fmt(state.checkReadings[selectedCheck],1)} · SET ${selectedCheck==='pressure'?'101.3':calibration[selectedCheck]}</span><div><i style="left:${clamp(state.checkReadings[selectedCheck],0,110)/110*100}%"></i><b style="left:${{power:45,engine:68,pressure:95}[selectedCheck]/110*100}%;width:${{power:20,engine:10,pressure:10}[selectedCheck]/110*100}%"></b></div><small>LMB holds test · Wheel adjusts setpoint into green</small></div>`:''}<div class="ce-expedition-bottom"><div class="ce-role-switch">${SPECIALISTS.map((n,i)=>`<button data-play-role="${i}" class="${i===role?'selected':''}" ${t.eliminated?'disabled':''} style="--character:#ef9953"><kbd>${i+1} / ${i===role?'HUMAN':'BOT'}</kbd><b>${n.name}</b><small>${n.role}</small></button>`).join('')}</div><div class="ce-role-abilities">${[['q','Q',r.skill,state.abilityCD[role]],['alt','MMB',r.secondary,state.altCD[role]],['f','F',r.ultimate,100-state.ultimate[role]]].map(([id,key,label,cd])=>`<button data-skill="${id}" ${t.eliminated?'disabled':''}><kbd>${key}</kbd><b>${label}</b><small>${cd>0?fmt(cd)+(id==='f'?'% TO CHARGE':'s'):'READY'}</small></button>`).join('')}</div><div class="ce-tool-label"><b>${r.weapon}</b><span>${phase==='surface'?'DELIVERY WINS THE MATCH':role===2?ammo[2]+' CELLS':'RETURN MARGIN MATTERS'}</span></div></div><div class="ce-toast ${toastTime>0?'visible':''}" role="status">${esc(toastText)}</div><div class="ce-controls-hint">WASD MOVE · V VIEW · 1–4 ROLES · B FOCUS · E INTERACT · G DROP FLAG · J MISSIONS · T SYSTEMS · X EVA / CUTAWAY · ESC MENU</div>`;if(hud.querySelector('.ce-job-panel'))hud.querySelector('.ce-job-panel').scrollTop=preservedJobScroll;}
function debrief(){unlock();if(state.match.teams[0].planet==='A'){setScene('home');ship.visible=true;pdf.update(false,true,time);}state.mode='debrief';state.ended=true;const r=scienceDebrief(state.match,0,{fuel:state.propellant,power:state.power});const c=buildScienceLog(state);state.won=r.victory;const payout=state.payout||debriefPayout(state,r,readProfile());if(!state.rewarded){state.rewarded=true;state.payout=payout;state.profile=payout.profile;try{localStorage.setItem('apogex-progress',JSON.stringify(state.profile));}catch{}}hud.hidden=true;menus.hidden=false;screen='debrief';menus.className='ce-screen ag-result-screen';menus.innerHTML=`<div class="ce-menu-header"><div class="ce-logo">APOG<span>EX</span><i>APOGEE: REIGNITE / SCIENCE LOG</i></div></div><div class="ce-debrief ce-sheet"><div class="ce-overline">${r.eliminated?'CREW ELIMINATED':r.victory?'VICTORY':state.match.winner===null?'MATCH COMPLETE / DRAW':'MATCH COMPLETE'}</div><h1>BRING IT <em>HOME.</em></h1><p>${r.delivered}/12 FLAGS DELIVERED. ${state.match.reason} Cargo carried or loaded never counted as a delivered point.</p><div class="ce-debrief-stats"><div><b>${r.delivered}/12</b><small>DELIVERED FLAGS</small></div><div><b>+${payout.xp} XP</b><small>BASE ${r.xp} + CONTRACT ${payout.contractXp}</small></div><div><b>+${payout.credits}</b><small>BASE ${r.credits} + CONTRACT ${payout.contractCredits}</small></div><div><b>#${r.rank}</b><small>DELIVERY RANK</small></div></div><div class="ag-final-scores">${rankTeams(state.match.teams).map(t=>`<span style="--team:${t.color}"><b>#${t.rank} ${t.symbol} ${t.name}${t.you?' (YOU)':''}</b>${t.delivered} DELIVERED${t.eliminated?' / ELIMINATED':''}</span>`).join('')}</div><section class="ag-science-log"><div class="ce-overline">PHASE 3 / MISSION CONTRACTS · ${payout.summary.done}/${payout.summary.total} COMPLETED</div>${payout.summary.cards.map(k=>`<article><b>${k.done?'✓':'○'} ${k.name}</b><strong>${k.value}/${k.max} ${k.done?'+'+k.xp+' XP':''}</strong><p>${k.detail}</p></article>`).join('')}</section><section class="ag-science-log"><div class="ce-overline">CREW CONTRIBUTION</div>${roleContribution(state).map(x=>`<article><b>${x.name} / ${x.role}</b><strong>${x.points} pts</strong><p>${x.parts} parts secured, ${x.cargo} cargo stowed</p></article>`).join('')}</section><section class="ag-science-log"><div class="ce-overline">REPLAY / KEY MOMENTS</div>${timelineText(state).map(e=>`<article><b>${Math.floor(e.t/60)}:${String(e.t%60).padStart(2,'0')}</b><p>${e.text}</p></article>`).join('')||'<article><p>No key moments recorded.</p></article>'}</section><section class="ag-science-log"><div class="ce-overline">TIPS FOR NEXT MATCH</div>${matchTips(state,r).map(x=>`<article><p>${x}</p></article>`).join('')}</section><section class="ag-science-log"><div class="ce-overline">SCIENCE LOG / ENGINEERING DECISIONS</div>${r.log.map(e=>`<article><b>${e.title}</b><strong>${e.value}</strong><p>${e.detail}</p></article>`).join('')}</section><section class="ag-science-log ag-cause"><div class="ce-overline">WHAT YOUR BUILD DID / CAUSE AND EFFECT</div>${c.entries.map(e=>`<article><b>${e.title}</b><strong>${e.value}</strong><p><em>BECAUSE</em>${e.cause}</p><p><em>SO</em>${e.effect}</p></article>`).join('')}</section><section class="ag-science-log ag-history"><div class="ce-overline">REAL HISTORY</div>${c.history.map(h=>`<article><b>${h.title}</b><strong>${h.year}</strong><p>${h.text}</p><p><em>YOUR SHIP</em>${h.link}</p></article>`).join('')}</section><div class="ag-progression"><span>LEVEL ${playerRank(state.profile?.xp||0).level} / ${playerRank(state.profile?.xp||0).label} · ${state.profile?.matches||0} MATCHES · PATCH: ${r.patch}</span><i><b style="width:${((state.profile?.xp||r.xp)%250)/250*100}%"></b></i></div><button class="ce-primary" data-screen="select">START ANOTHER MATCH ↗</button><button class="ce-secondary" data-action="planner">MISSION DESIGN & SCIENCE SIMULATOR</button></div>`;}
function cinematicStep(dt){intro+=dt;const LEN=15,shot=Math.min(4,Math.floor(intro/3));$('ce-cinema-progress').style.width=Math.min(100,intro/LEN*100)+'%';ship.visible=false;world.rivals.children.forEach(g=>g.children.forEach(o=>{if(o.userData.rocket)o.visible=false;}));const mm=document.getElementById('ag-map');if(mm)mm.style.display='none';const shots=[['YOUR SPECIALIST',SPECIALISTS[state.selected].name+' / '+SPECIALISTS[state.selected].role,'Choose your view. Know your tools. Every job matters.'],['YOUR TEAM',state.teams[0].name+' / FOUR RESPONSIBILITIES','Pilot, Engineer, Gunner and Raider gather. Every crew has all four jobs.'],['LET\'S GO',"WE CAN DO THIS!",'Hands in, hands up. One crew, one rocket, one frontier.'],['THE COMPETITION','THREE RIVAL CREWS. ONE FRONTIER.','Orange / Cyan / Violet / Lime. One player and fifteen bots.'],['THE MISSION','BUILD. CAPTURE. RETURN.','Commander Ines Valder: Bring the Science Flags home. Cargo aboard is not a delivered point.']];$('ce-cinema-label').textContent=shots[shot][0];$('ce-cinema-title').textContent=shots[shot][1];$('ce-cinema-copy').textContent=shots[shot][2];const C=new THREE.Vector3(0,0,14),t1=Math.min(1,Math.max(0,(intro-3)/2.5)),cheer=Math.max(0,intro-7.5);world.actors.forEach((a,i)=>{const g=a.group,home=new THREE.Vector3(-4+i*1.6,0,8),ang=i/4*Math.PI*2+.6,ring=new THREE.Vector3(C.x+Math.cos(ang)*(1.4-Math.min(1,Math.max(0,(intro-6)/1.5))*.45),0,C.z+Math.sin(ang)*(1.4-Math.min(1,Math.max(0,(intro-6)/1.5))*.45));if(intro<3)g.position.copy(home);else g.position.lerpVectors(home,ring,t1);const face=intro<3?0:Math.atan2(C.x-g.position.x,C.z-g.position.z);g.rotation.y=face;let hop=0;if(cheer>0&&intro<9.4)hop=Math.abs(Math.sin(cheer*5.2))*.55;g.position.y=hop;const up=intro>=6.6;a.arms.forEach((l,k)=>{l.rotation.x=up?(intro<7.5?-1.2:-3):0;});animateActor(a,dt,intro>3&&intro<5.5);});world.rivals.children.forEach((g,gi)=>{g.children.forEach(o=>{});});const rc=world.rivals.children.map(g=>g.position.clone().add(new THREE.Vector3(0,0,22)));let pos,target;if(shot===0){const a=world.actors[state.selected].group.position;pos=a.clone().add(new THREE.Vector3(2.4,1.9,4.5-intro*.3));target=a.clone().add(new THREE.Vector3(0,1.3,0));}if(shot===1){pos=C.clone().add(new THREE.Vector3(Math.sin(intro)*4,2.4,-7+Math.cos(intro)*1));pos=C.clone().add(new THREE.Vector3(Math.sin(intro*.8)*9,3,Math.cos(intro*.8)*9));target=C.clone().add(new THREE.Vector3(0,1.1,0));}if(shot===2){pos=C.clone().add(new THREE.Vector3(4.6,2,7));target=C.clone().add(new THREE.Vector3(0,1.5,0));}if(shot===3){const k=Math.min(2,Math.floor((intro-9)/1)),p=rc[k]||rc[0];pos=p.clone().add(new THREE.Vector3(0,2.6,8));target=p.clone().add(new THREE.Vector3(0,1.2,0));}if(shot===4){pos=C.clone().add(new THREE.Vector3(5,3,9));target=C.clone().add(new THREE.Vector3(0,1.3,0));}const shotKey=shot===3?30+Math.min(2,Math.floor(intro-9)):shot;if(cinematicStep.last!==shotKey||intro<.1){cinematicStep.last=shotKey;camera.position.copy(pos);}else camera.position.lerp(pos,Math.min(1,dt*(shot===3?6:3)));camera.lookAt(target);camera.fov=50;camera.updateProjectionMatrix();if(shot===3||shot===2)world.rivals.children.forEach(g=>g.children.forEach(o=>{}));rivalCheer(dt);if(intro>=LEN)beginAssembly();}
function rivalCheer(dt){const up=intro>=7.5;world.rivals.children.forEach((g,gi)=>{(g.userData.crewActors||[]).forEach((a,i)=>{a.group.position.y=.22+(up?Math.abs(Math.sin(intro*5+i+gi))*.4:0);a.arms.forEach(l=>{l.rotation.x=up?-3:0;});animateActor(a,dt,false);});});}
function update(dt){if(!active||wasPlanning)return;api.clearDesignPreview?.();if(!fpsOn())fpsv.setVisible(false);time+=dt;updateBuildArms(dt);if(screen&&state.mode!=='cutscene'){if((screen==='route'||screen==='gonogo')&&!state.paused){state.elapsed+=dt;tickRivals(state,dt);}world.showcase.forEach((v,i)=>{v.avatar.group.rotation.y=Math.sin(time*.3+i)*.1;v.avatar.skin?.mixer.update(dt);if(v.avatar.head)v.avatar.head.rotation.z=Math.sin(time*.45+i)*.035;});pdf.update(false,['route','gonogo','assign','shop'].includes(screen),time);return;}if(state.mode==='launch'){launchStep(dt);return;}if(state.mode==='cutscene'){cinematicStep(dt);pdf.update(false,true,time);return;}if(state.mode!=='play'||state.paused)return;state.elapsed+=dt;state.match.teams[0].botPosition=world.actors[3].group.position.toArray();tickRivals(state,dt*(state.phase==='spectator'?spectatorSpeed:1));if(state.match.over){debrief();return;}if(state.phase==='spectator'){spectatorCamera(dt);hudClock-=dt;if(hudClock<=0){hudClock=.2;updateHUD();}return;}
for(let i=0;i<4;i++){if(reloadTimers[i]>0){reloadTimers[i]-=dt;if(reloadTimers[i]<=0)ammo[i]=[24,18,20,16][i];}if(state.phase!=='flight'){state.abilityCD[i]=Math.max(0,state.abilityCD[i]-dt);state.altCD[i]=Math.max(0,state.altCD[i]-dt);state.ultimate[i]=Math.min(100,state.ultimate[i]+dt*.4);}}fireClock=Math.max(0,fireClock-dt);const priorPhase=state.phase,shipBefore=ship.position.clone();collisionFrame=null;updateMovement(dt);updateAI(dt);collideGround();
// Only grounded gameplay phases: EVA/ship flight must never be snapped to terrain.
if(['assembly','outfit','surface','delivery'].includes(state.phase)){
 const surfaceY=state.phase==='surface' ? -.10 : null;ship.traverse(o=>{if(o.userData.landingGear)o.scale.y=1;}); // top of Planet B's frontier cylinder
 world.actors.forEach(a=>{const p=a.group.position;p.y=(surfaceY??floorHeightAt(p.x,p.z))+(a.motor?.y||0);});
}if(state.phase==='flight'&&state.selected===3&&state.eva)world.actors[3].group.position.add(ship.position.clone().sub(shipBefore));
world.rivalShips.forEach(v=>{const t=state.match.teams[v.team.id],count=Math.ceil(clamp(t.progress/.3,0,1)*v.craft.children.length);if(t.planet==='A'&&t.phase==='building')v.craft.children.forEach((o,i)=>o.visible=i<count&&!o.userData.engineFlame);});world.updateVisuals();buildAnim(dt);pdf.update(state.phase==='surface',['assembly','outfit','route','delivery'].includes(state.phase),time);updateCamera(dt);lastHit=target();tool(dt);fpsFrame(dt);guideFrame();mapFrame(dt);
if(state.phase==='flight'){tickSystems(state,dt);state.match.teams[0].hull=state.hull*20;if(state.phase==='spectator'){resumeSpectating();return;}updateCombat(dt);if(state.flightTime>=(state.flightLeg==='return'?60:state.route.duration))completeFlight(state);}else if(state.phase==='surface'){updateCombat(dt);state.scanBoost=Math.max(0,state.scanBoost-dt);state.shield=Math.max(0,state.shield-dt);}
if(state.phase==='landing'){beginSurface();return;}if(state.phase==='docking'){beginDock();return;}if(state.phase==='outfit'&&priorPhase==='assembly'){ship.visible=true;announce('Spacecraft complete. Load supplies and verify pressure, power and engine tests.');}if(state.phase==='route'){renderRoute();return;}
for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.life-=dt;p.mesh.position.addScaledVector(p.v,dt);p.v.y-=dt*3;if(p.life<=0){p.mesh.removeFromParent();particles.splice(i,1);}}toastTime=Math.max(0,toastTime-dt);if(state.mode==='play'&&state.phase!=='spectator')reportCompletedContracts();hitPulse=Math.max(0,hitPulse-dt);hitFeedback.style.opacity=String(Math.min(1,hitPulse*3));hudClock-=dt;if(hudClock<=0){hudClock=.12;updateHUD();}}
function rivalRoster(){return `<aside class="ag-roster"><div class="ce-overline">RIVAL CREWS / 12 BOTS</div>${FACTIONS.slice(1).map(t=>`<section style="--team:${t.color}"><b>${t.symbol} ${t.name}</b><div>${SPECIALISTS.map(r=>`<span title="${r.name} / ${r.role}">${['🐸','🤖','🐝','🦩'][r.id]}<small>BOT</small></span>`).join('')}</div></section>`).join('')}<p>ORANGE: ${SPECIALISTS.map((r,i)=>r.role+' '+(i===state.selected?'HUMAN':'BOT')).join(' · ')}<br>OFFLINE · 16/16 READY</p></aside>`;}
function procurementPanel(){const reserve=state.parts.filter(p=>!p.purchased).reduce((a,p)=>a+p.price,0);return `<div class="ag-shop"><div class="ce-overline">CREDITS ${state.credits.toLocaleString()} / CORE PARTS RESERVED ${reserve}</div><p>More weapons, more cargo, or more reserve — you cannot maximize everything.</p><div>${UPGRADES.map(u=>`<button data-upgrade="${u.id}" ${!state.upgrades.includes(u.id)&&state.credits-reserve<u.cost?'disabled':''} class="${state.upgrades.includes(u.id)?'selected':''}"><b>${u.name}</b><small>${u.cost} CREDITS · +${u.mass} kg · +${u.power} kW</small><span>${u.description}</span><em>${state.upgrades.includes(u.id)?'INSTALLED ✓':'BUY OPTION'}</em></button>`).join('')}</div><p class="ag-cutaway-labels">FUEL ${fmt(state.propellant)} kg · POWER ${fmt(state.power,1)} kWh · LIFE SUPPORT · CARGO ${state.cargoCapacity} FLAGS · WEAPONS ${state.upgrades.includes('weapons')?'HEAVY':'STANDARD'} · RETURN MARGIN</p>${designPanel()}</div>`;}
function flightRepair(){const fault=state.fault,kind=FAULT_REPAIR[fault];if(!kind||state.phase!=='flight'||state.mode!=='play'||state.paused||repairing||state.match.teams[0].eliminated)return;repairing=true;state.paused=true;keys.clear();pointer.left=false;pointer.right=false;workToggle=false;unlock();const host=document.createElement('div');host.className='ag-flight-repair';document.body.appendChild(host);let close=null;const esc=e=>{if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();close?.();}};addEventListener('keydown',esc,true);close=openRepair(host,kind,designSheet(state),state.seed+Math.floor(state.flightTime),res=>{if(res.ok&&state.fault===fault){maintainSystem(state,1,6,fault==='scrubber'?'scrubber':'reactor');state.handRepairs=(state.handRepairs||0)+1;(state.repairLog??=[]).push({fault,kind,seconds:res.seconds,attempts:res.attempts});announce('Repaired by hand in '+res.seconds.toFixed(0)+' s');}},()=>{removeEventListener('keydown',esc,true);host.remove();repairing=false;state.paused=false;});}
let countdownTimer=null,spectatorFree=false;
function stopCountdown(msg){if(countdownTimer){clearInterval(countdownTimer);countdownTimer=null;}if(msg&&screen==='gonogo'){const el=menus.querySelector('.ag-poll-actions');if(el){el.innerHTML=`<span class="ag-poll-summary" data-status="caution">${msg}</span><button class="ce-text" data-backroute>← BACK TO ROUTES</button><button class="ce-primary" data-launch="${pendingRoute}">RESUME LAUNCH ↗</button>`;}}}
function startCountdown(id){stopCountdown();let n=5;const el=menus.querySelector('.ag-poll-actions');const show=()=>{if(el)el.innerHTML=`<span class="ag-poll-summary" data-status="go">T-MINUS ${n}</span><button class="ce-secondary" data-hold>HOLD</button><button class="ce-secondary" data-abort>ABORT</button>`;};show();countdownTimer=setInterval(()=>{if(screen!=='gonogo'){stopCountdown();return;}n--;if(n<=0){stopCountdown();beginFlight(id);return;}show();},1000);}
function renderGoNoGo(id){stopCountdown();unlock();pendingRoute=id;menus.hidden=false;hud.hidden=true;screen='gonogo';setScene('build');ship.visible=true;world.assembly.visible=false;menus.className='ce-screen ce-route-screen';const p=goNoGo(state,id),f=i=>!Number.isFinite(i.value)?'—':(i.id==='twr'?i.value.toFixed(2):i.id==='downlink'?i.value.toFixed(0):i.value.toFixed(1))+' '+i.unit,tag={go:'GO',caution:'CAUTION',nogo:'NO-GO'},goCount=p.roles.filter(r=>r.status!=='nogo').length;menus.innerHTML=`<div class="ce-menu-header"><div class="ce-logo">APOG<span>EX</span><i>GO / NO-GO POLL</i></div><button class="ce-text" data-action="pause">GAME MENU ↗</button></div><div class="ce-route-heading"><div class="ce-overline">${p.route.name.toUpperCase()} / ${fmt(state.wetMass)} KG WET MASS</div><h1>ALL STATIONS, <em>REPORT.</em></h1><p>Each crew member answers for their own systems. Any NO-GO holds the launch; a CAUTION lets you go but tells you what it will cost.</p></div><div class="ag-poll">${p.roles.map(r=>{const lead=r.items.reduce((a,i)=>RANK[i.status]>RANK[a.status]?i:a,r.items[0]);return `<article class="ag-poll-card" data-status="${r.status}"><header><span>${r.role}</span><b>${r.name}</b><em>${r.call}</em></header><ul>${r.items.map(i=>`<li data-status="${i.status}"><b>${i.label}</b><span>${f(i)}</span><small>${tag[i.status]} · ${i.limit}</small></li>`).join('')}</ul><p>${lead.why}</p></article>`;}).join('')}</div><div class="ag-poll-actions"><span class="ag-poll-summary" data-status="${p.status}">${goCount} OF 4 STATIONS CLEAR${p.cautions.length?' · '+p.cautions.length+' CAUTION'+(p.cautions.length>1?'S':''):''}</span><button class="ce-text" data-backroute>← BACK TO ROUTES</button><button class="ce-primary" data-launch="${id}" ${p.canLaunch?'':'disabled'}>${p.canLaunch?(p.cautions.length?'ACCEPT CAUTION & LAUNCH':'ALL GO — LAUNCH'):'NO-GO — LAUNCH HELD'} ↗</button></div>`;}
const sfx=createSfx(()=>muted),fpsv=createFpsView({camera,scene,sfx});fpsv.loadModels().catch(()=>{});sfx.load();
const fps={load:FPS.createLoadout(),vitals:FPS.createVitals(),inp:IN.createInput(),grenades:[],ads:false,fireHeld:false,firePressed:false,eye:FPS.EYE_STAND,stepClock:1.6,sprinting:false,moving:false,crouch:false,carrying:false,speed:0,fov:70};
const fpsOn=()=>state.phase==='surface'&&state.mode==='play'&&!state.paused&&!screen&&!state.match.teams[0].eliminated;
const lookOn=()=>IN.isLook(fps.inp);
function fpsReset(){fps.load=FPS.createLoadout();FPS.resetVitals(fps.vitals);fps.grenades.forEach(g=>g.mesh?.removeFromParent());fps.grenades=[];fps.ads=fps.fireHeld=fps.firePressed=false;fps.eye=FPS.EYE_STAND;}
function toggleLook(){const m=IN.toggleCursor(fps.inp);fps.ads=fps.fireHeld=fps.firePressed=false;if(m==='look')lock();else unlock();announce(m==='look'?'LOOK MODE · the mouse turns the camera · TAB for cursor':'CURSOR MODE · click the screen · TAB to look');}
function fpsSwitch(i){if(FPS.switchTo(fps.load,i)){sfx.play('reload_click',{volume:.4});announce(FPS.currentWeapon(fps.load).name);}}
function fpsReload(){const w=FPS.currentWeapon(fps.load),g=FPS.currentGun(fps.load);if(FPS.startReload(fps.load))sfx.play('reload_ratchet',{volume:.5});else if(g.mag<w.mag&&g.reserve<=0)announce('NO RESERVE AMMO · switch weapon (1-3)');}
function fpsTargets(){const out=[];for(const t of state.match.teams.slice(1)){if(t.eliminated||t.planet!=='B')continue;out.push({id:'bot'+t.id,kind:'bot',team:t,center:[t.botPosition[0],t.botPosition[1]+1.1,t.botPosition[2]],radius:.85});out.push({id:'hull'+t.id,kind:'hull',team:t,center:[t.position[0],t.position[1]+4.5,t.position[2]],radius:8});}return out;}
function fpsCovers(){return pdf.cover.map(c=>({id:'cover',kind:'cover',center:[c.position.x,c.position.y,c.position.z],radius:c.radius}));}
function damageBot(t,dmg,point){dropFlag(state.match,t.id,3,t.botPosition,'B');t.stun=1.2;t.fieldHealth=(t.fieldHealth??100)-dmg;let kill=false;if(t.fieldHealth<=0){t.botPosition=[...LANDING_BAYS[t.id]];t.fieldHealth=100;t.stun=4;kill=true;state.kills++;announce(FACTIONS[t.id].name+' crew member down · flags dropped.');}sparks(point,t.color,3);return kill;}
function fpsHurt(amount){const r=FPS.damage(fps.vitals,amount);if(r.shieldBroke)sfx.play('shield_break',{volume:.7});else if(r.shield>0&&r.health===0)sfx.play('shield_hit',{volume:.6});if(r.health>0)sfx.play('hurt',{volume:.6});return r;}
function fpsFire(){const w=FPS.currentWeapon(fps.load),r=FPS.fire(fps.load,{ads:fps.ads,crouch:fps.crouch,moving:fps.moving,sprint:fps.sprinting});
if(!r.ok){if(r.reason==='empty'){sfx.tone(900,.05);if(FPS.startReload(fps.load))sfx.play('reload_ratchet',{volume:.5});else announce('OUT OF AMMO · switch weapon (1-3)');}return;}
const origin=camera.getWorldPosition(new THREE.Vector3()),fw=direction().toArray();fpsv.onFire(w.id,r.recoil.pitch);pitch=clamp(pitch+r.recoil.pitch,-1.1,1.1);yaw+=r.recoil.yaw;
const all=fpsTargets().concat(fpsCovers()),muzzle=fpsv.muzzleWorld(w.id);let anyHit=false,kill=false;
for(const s of r.shots){const d=FPS.applySpread(fw,s.yaw,s.pitch),h=FPS.firstHit(origin.toArray(),d,all,w.range),dv=new THREE.Vector3(...d),end=dv.clone().multiplyScalar(h?h.distance:w.range).add(origin);if(w.pellets===1||Math.random()<.5)fpsv.tracer(muzzle,end,'#ffe0a0');
if(h){const tg=h.target,dmg=s.damage*FPS.falloff(w,h.distance);if(tg.kind==='bot'){anyHit=true;kill=damageBot(tg.team,dmg,end)||kill;}else if(tg.kind==='hull'){anyHit=true;damageCrew(state.match,tg.team.id,dmg*4,tg.team.position,'B');fpsv.impact(end,tg.team.color);}else fpsv.impact(end);}}
if(anyHit){recordCrewAction(state,'combatHits');fpsv.hitMarker(kill);pulseHitFeedback(kill);}}
function fpsGrenade(){if(fps.load.grenades<=0){announce('NO GRENADES LEFT');return;}const o=camera.getWorldPosition(new THREE.Vector3()).addScaledVector(direction(),.4),g=FPS.throwGrenade(fps.load,o.toArray(),direction().toArray(),fps.speed);if(!g)return;g.mesh=fpsv.spawnGrenadeMesh();fps.grenades.push(g);fpsv.throwAnim();sfx.play('reload_click',{volume:.5});}
function fpsGrenades(dt){for(let i=fps.grenades.length-1;i>=0;i--){const g=fps.grenades[i];FPS.stepGrenade(g,dt,0);g.mesh.position.set(g.pos[0],g.pos[1],g.pos[2]);g.mesh.rotation.x+=dt*8;
if(g.exploded){const p=new THREE.Vector3(...g.pos);fpsv.explosion(p);for(const tg of fpsTargets()){const dist=tg.kind==='bot'?Math.hypot(tg.center[0]-p.x,tg.center[1]-p.y,tg.center[2]-p.z):Math.max(0,Math.hypot(tg.center[0]-p.x,tg.center[2]-p.z)-tg.radius),dmg=FPS.explosionDamage(dist);if(dmg<=0)continue;if(tg.kind==='bot')damageBot(tg.team,dmg,p);else damageCrew(state.match,tg.team.id,dmg*4,tg.team.position,'B');}
const me=world.actors[state.selected].group.position,self=FPS.explosionDamage(Math.hypot(me.x-p.x,me.y+1-p.y,me.z-p.z))*.6;if(self>0)fpsHurt(self);g.mesh.removeFromParent();fps.grenades.splice(i,1);}}}
function fpsFrame(dt){const on=fpsOn();document.body.classList.toggle('fps-look',on&&lookOn());if(!on){fpsv.setVisible(false);fps.ads=false;fps.fireHeld=false;return;}
const role=state.selected,moving=['w','a','s','d'].some(k=>keys.has(k)),fwd=keys.has('w')&&!keys.has('s'),carrying=state.match.flags.some(f=>f.state==='carried'&&f.carrier===role&&f.owner===0);
fpsv.setVisible(state.views[state.selected]==='first');fps.crouch=keys.has('c')||keys.has('control');fps.moving=moving;fps.carrying=carrying;
fps.sprinting=FPS.isSprinting({sprint:keys.has('shift'),crouch:fps.crouch,ads:fps.ads,carrying,moving,forward:fwd});
fps.speed=moving?FPS.moveSpeed({sprint:keys.has('shift'),crouch:fps.crouch,ads:fps.ads,carrying,forward:fwd}):0;
if(!lookOn()){fps.fireHeld=false;fps.ads=false;}
const w=FPS.currentWeapon(fps.load);if(fps.firePressed||(w.auto&&fps.fireHeld))fpsFire();fps.firePressed=false;
if(FPS.tickLoadout(fps.load,dt).reloaded)sfx.play('reload_click',{volume:.5});if(FPS.tickVitals(fps.vitals,dt))sfx.play('shield_recharge',{volume:.5});
fps.eye=FPS.approach(fps.eye,fps.crouch?FPS.EYE_CROUCH:FPS.EYE_STAND,10,dt);fpsGrenades(dt);
if(moving){fps.stepClock+=dt*fps.speed;if(fps.stepClock>2.3){fps.stepClock=0;sfx.play('step_'+(Math.random()*4|0),{volume:fps.sprinting?.35:fps.crouch?.1:.22});}}else fps.stepClock=1.6;
let cap=null;if(keys.has('e')&&lastHit?.type==='science'){const f=state.match.flags[lastHit.id];if(f&&f.state==='site')cap={frac:((f.stage||0)+f.progress)/3,label:['SCAN','STABILIZE','EXTRACT'][f.stage||0]};}
const res=fpsv.update({loadout:fps.load,ads:fps.ads,sprinting:fps.sprinting,crouch:fps.crouch,moving,speed:fps.speed,dt,look:{yaw,pitch}});fps.fov=res?.fov??70;
fpsv.updateHud({visible:true,loadout:fps.load,vitals:fps.vitals,spread:FPS.spreadAngle(fps.load,{ads:fps.ads,crouch:fps.crouch,moving,sprint:fps.sprinting}),ads:fps.ads,sprinting:fps.sprinting,crouch:fps.crouch,cursor:!lookOn(),capture:cap,carrying});}
let lastRot=0;
const guideBeam=new THREE.Mesh(new THREE.CylinderGeometry(.5,.5,80,16,1,true),new THREE.MeshBasicMaterial({color:'#7fd69a',transparent:true,opacity:.35,depthWrite:false,blending:THREE.AdditiveBlending,side:THREE.DoubleSide}));guideBeam.visible=false;scene.add(guideBeam);
const guideZone=new THREE.Mesh(new THREE.PlaneGeometry(1,1),new THREE.MeshBasicMaterial({color:'#7fd69a',transparent:true,opacity:.28,depthWrite:false,side:THREE.DoubleSide}));guideZone.rotation.x=-Math.PI/2;guideZone.visible=false;scene.add(guideZone);
function guideHtml(role){const pos=world.actors[role].group.position,st=BG.buildStep(state,role,pos.x,pos.z),g=BG.guideText(st);return `<div class="ag-guide" data-step="${st.id}"><div class="steps">${[1,2,3,4,5].map(n=>`<i class="${n===g.n?'on':n<g.n?'done':''}">${n}</i>`).join('')}</div><b>${g.title}</b>${g.lines.map(l=>`<p>${l}</p>`).join('')}<div class="mouse">${g.mouse.map(x=>`<span>${x}</span>`).join('')}</div></div>`;}
function guideFrame(){guideBeam.visible=guideZone.visible=false;if(!(state.phase==='assembly'&&state.mode==='play'&&!state.paused&&!screen))return;const role=state.selected,pos=world.actors[role].group.position,st=BG.buildStep(state,role,pos.x,pos.z),pulse=.5+.5*Math.sin(time*4);let tx,tz,color='#7fd69a',zone=null;
if(st.id==='pickup'){const v=world.partVisuals.find(v=>v.part===st.part);tx=v.shelf.position.x;tz=v.shelf.position.z;color='#f7ce59';zone={cx:tx,cz:tz,hx:1.7,hz:1.7};}
else if(st.id==='rotate'||st.id==='walk'||st.id==='place'){const f=BG.footprint(st.part);tx=f.cx;tz=f.cz;zone=f;color=st.id==='place'?'#7fd69a':'#f7ce59';}
else if(st.id==='fasten'){const v=world.partVisuals.find(v=>v.part===st.part),b=v.bolts[Math.max(0,st.bolt)];tx=b.position.x;tz=b.position.z;color='#80e6c1';}else return;
const thin=st.id==='fasten'?.9:2.2;guideBeam.position.set(tx,40,tz);guideBeam.scale.set(thin,1,thin);guideBeam.material.color.set(color);guideBeam.material.opacity=.3+.28*pulse;guideBeam.visible=true;
if(zone){guideZone.position.set(zone.cx,.08,zone.cz);guideZone.scale.set(zone.hx*2,zone.hz*2,1);guideZone.material.color.set(color);guideZone.material.opacity=.22+.2*pulse;guideZone.visible=true;}}
const mapv=createMinimapView();let mapClock=0;
function mapFrame(dt){const phase=state.phase,on=state.mode==='play'&&!screen&&!state.paused&&phase!=='spectator';mapv.setVisible(on);if(!on)return;mapClock-=dt;if(mapClock>0)return;mapClock=.07;
const role=state.selected,pp=world.actors[role].group.position,flying=phase==='flight';
const center=flying?{x:ship.position.x,z:ship.position.z}:{x:pp.x,z:pp.z},yawNow=flying?0:yaw,player={x:center.x,z:center.z};
const ctx={phase,player,actors:world.actors.map(a=>({x:a.group.position.x,z:a.group.position.z})),ship:{x:ship.position.x,z:ship.position.z,upright:Math.abs(ship.rotation.x)>.8},objective:lastObjective};
if(flying){ctx.actors=[];ctx.hazards=hazards.map(h=>({x:h.mesh.position.x,z:h.mesh.position.z}));ctx.enemies=enemies.map(e=>({x:e.mesh.position.x,z:e.mesh.position.z,color:e.teamColor}));}
if(phase==='assembly'){const st=BG.buildStep(state,role,pp.x,pp.z);if(st.part){const f=BG.footprint(st.part);ctx.currentPart={cx:f.cx,cz:f.cz,hx:f.hx,hz:f.hz};}}
if(phase==='outfit'){ctx.stow={x:0,z:STOW_Z};ctx.checks=world.checks.map(c=>({id:c.id,x:c.position[0],z:c.position[2],color:c.color}));}
if(phase==='surface'){ctx.flags=state.match.flags.map(f=>({x:f.position[0],z:f.position[2],state:f.state}));ctx.rivals=state.match.teams.slice(1).filter(t=>t.planet==='B').map(t=>({x:t.position[0],z:t.position[2],bx:t.botPosition[0],bz:t.botPosition[2],color:t.color,eliminated:t.eliminated}));}
if(phase==='delivery')ctx.receiver={x:pdf.receiver.position.x,z:pdf.receiver.position.z};
const c=flagCounts(state.match,0);
mapv.draw({phase,center,yaw:yawNow,entities:collectEntities(state,ctx),legend:ctx,counts:'FLAGS '+c.sites+' AT SITES · '+c.onboard+' ONBOARD · '+c.delivered+' DELIVERED'});}
function designPanel(){const d=designSheet(state),f=(v,n=1)=>Number.isFinite(v)?v.toFixed(n):'—',label={go:'GO',caution:'CAUTION',nogo:'NO-GO'};const val=c=>c.id==='twr'?f(c.value,2):c.id==='downlink'?f(c.value,0):f(c.value,1);return `<div class="ag-design" data-overall="${d.overall}"><div class="ce-overline">DESIGN SHEET / LIVE · ${d.installed}/${state.parts.length} PARTS SECURED</div><p class="ag-design-mass">DRY ${f(d.mass.dry,0)} kg + FUEL ${f(d.mass.propellant,0)} kg = WET <b>${f(d.mass.wet,0)} kg</b> · THRUST ${f(d.thrustKN,1)} kN · GENERATION ${f(d.power.generationKW,1)} kW vs LOAD ${f(d.power.loadKW,2)} kW</p><div class="ag-design-grid">${d.checks.map(c=>`<details class="ag-design-check" data-status="${c.status}"><summary><span>${c.label}<small> · ${ROOM_LABEL[c.room]}</small></span><b>${val(c)} ${c.unit}</b><em>${label[c.status]} · ${c.limit}</em></summary><p>${c.why}</p></details>`).join('')}</div><p class="ag-design-note">Every option adds mass or power load. Open a line to see the formula behind it. Ship model: ${interior?ROOM_ORDER.filter(r=>namedNodes(interior).has('module_'+r)).length+' rooms loaded':'loading'}.</p><button class="ce-text ag-walk-open" type="button" data-walk>WALK THE SHIP ↗</button></div>`;}
function clearEncounter(){for(const list of[bullets,enemies,hazards])for(const x of list)x.mesh.removeFromParent();bullets=[];enemies=[];hazards=[];}
function beginSurface(){state.views[state.selected]='first';clearEncounter();state.phase='surface';state.flightLeg='outbound';state.match.teams[0].phase='surface';state.match.teams[0].planet='B';state.match.teams[0].position=[...LANDING_BAYS[0]];state.match.teams[0].botPosition=[0,0,LANDING_BAYS[0][2]-20];state.eva=false;setScene('surface');ship.visible=true;ship.position.set(0,SHIP_Y-.32,LANDING_BAYS[0][2]);ship.rotation.set(0,0,0);world.actors.forEach((a,i)=>{a.group.visible=true;a.group.position.set(-3+i*2,0,LANDING_BAYS[0][2]-20);});screen=null;menus.hidden=true;hud.hidden=false;state.mode='play';yaw=0;pitch=-.05;resetLocomotion();announce('PLANET B · '+flagsAtSites(state.match)+' finite Science Flags at sites. RAIDER: aim at a sample site and HOLD E to capture. LMB fires. E loads cargo at the ship.');}
function beginReturn(){const t=state.match.teams[0];t.carrying=state.match.flags.find(f=>f.state==='carried'&&f.owner===0)?.id??null;if(!departFrontier(state.match,0)){announce('Load or drop the carried flag before departure.');return;}const count=flagCounts(state.match,0).onboard;state.route.returnReserve=(state.wetMass-state.route.outbound+count*6)*(1-Math.exp(-95/state.route.exhaust));if(state.propellant<state.route.returnReserve){t.phase='surface';t.planet='B';announce('Return fuel insufficient. Reduce cargo or recover reserves.');return;}mark(state,'Left Planet B with '+count+' flags');clearEncounter();state.phase='flight';state.flightLeg='return';state.flightTime=0;state.eva=false;setScene('flight');ship.position.set(0,1.4,5);positionFlightActors();announce('FLAGS ONBOARD: '+count+' · DELIVERED: '+flagCounts(state.match,0).delivered+' · Defend the return to Planet A.');}
function beginDock(){clearEncounter();{const on=state.match.flags.filter(f=>f.state==='onboard'&&f.owner===0);let n=state.match.seed+Math.floor(state.flightTime)*31;const rnd=()=>{n=(n*1664525+1013904223)>>>0;return n/4294967296;};if(rollRaid(state,on.length,rnd)){const f=on[0];f.state='delivered';f.owner=1+Math.floor(rnd()*3);mark(state,'RAID: a rival crew intercepted one flag on approach');announce('RAID! A rival crew intercepted one of your flags.');}else if(on.length)mark(state,'Delivery approach was clear');}state.phase='delivery';arriveHome(state.match,0);setScene('home');ship.position.set(0,SHIP_Y,0);ship.rotation.set(0,0,0);world.assembly.visible=false;ship.visible=true;world.actors.forEach((a,i)=>{a.group.position.set(-2+i*1.4,0,24);a.group.visible=true;});state.eva=false;screen=null;menus.hidden=true;hud.hidden=false;resetLocomotion();announce('PLANET A RECEIVING STATION · Walk to the receiver and press E for each flag. Only delivered flags score.');}
function toggleExterior(){if(state.phase==='flight'&&state.selected===3){state.eva=!state.eva;positionFlightActors();announce(state.eva?'EVA tether active. E removes damaged plates; LMB repairs.':'Returned to scanner / cargo deck.');}else if(['assembly','outfit'].includes(state.phase)){state.cutaway=!state.cutaway;ship.traverse(o=>{if(o.userData.hullShell)o.visible=!state.cutaway;});world.partVisuals.forEach(v=>{if(v.part.stage==='secured')v.install.visible=state.cutaway;});announce(state.cutaway?'CUTAWAY · FUEL / POWER / LIFE SUPPORT / CARGO / WEAPONS':'Hull view restored.');}}
function resumeSpectating(){clearEncounter();state.mode='play';screen=null;state.paused=false;menus.hidden=true;hud.hidden=false;world.viewmodel.visible=false;world.cockpitFrame.visible=false;announce(state.match.teams[0].eliminated?'CREW ELIMINATED · Cargo recovery beacon remains. SPECTATE surviving crews.':'Flags delivered. Watching the other crews finish.');}
function spectatorCamera(dt){const t=state.match.teams[spectatorTeam];const surface=t.planet==='B';setScene(surface?'surface':t.planet==='A'?'home':'flight');world.actors.forEach(a=>a.group.visible=false);ship.visible=false;const p=surface?new THREE.Vector3(...t.botPosition):t.planet==='A'?new THREE.Vector3(...LANDING_BAYS[t.id]):new THREE.Vector3(0,1,0);camera.position.lerp(p.clone().add(new THREE.Vector3(12,12,17)),1-Math.exp(-dt*3));camera.lookAt(p);camera.fov=55;camera.updateProjectionMatrix();pdf.update(surface,t.planet==='A',time);}
menus.addEventListener('click',event=>{const b=event.target.closest('button,[data-screen]');if(!b||b.disabled)return;if(b.dataset.upgrade){setUpgrade(state,b.dataset.upgrade,!state.upgrades.includes(b.dataset.upgrade));renderMenu();return;}if(b.dataset.buildStyle){setConstructionStyle(state,b.dataset.buildStyle);renderMenu();return;}if(b.dataset.role!==undefined){state.selected=Number(b.dataset.role);renderMenu();return;}if(b.dataset.diff){applyOptions(state,{difficulty:b.dataset.diff,length:state.options?.length||'standard'});renderMenu();return;}if(b.dataset.len){applyOptions(state,{difficulty:state.options?.difficulty||'standard',length:b.dataset.len});renderMenu();return;}if(b.dataset.action==='ready'){toggleReady(lobby);renderMenu();return;}if(b.dataset.action==='chat'){const inp=document.getElementById('ce-chat-input');if(inp&&postChat(lobby,'You',inp.value)){try{lobbyChannel?.postMessage({code:lobby.code,who:'Crew',text:inp.value});}catch{}postChat(lobby,SPECIALISTS[(Date.now()>>10)%4].name,botReply(lobby.chat.length));}renderMenu();return;}if(b.dataset.action==='free-cam'){spectatorFree=!spectatorFree;return;}if(b.dataset.route){renderGoNoGo(b.dataset.route);return;}if(b.dataset.launch){startCountdown(b.dataset.launch);return;}if(b.dataset.hold!==undefined){stopCountdown('HOLD: countdown stopped. Fix the issue or press launch again.');return;}if(b.dataset.abort!==undefined){stopCountdown();renderRoute();return;}if(b.dataset.backroute!==undefined){renderRoute();return;}const action=b.dataset.action;if(action==='return'){beginReturn();return;}if(action==='results'){spectatorSpeed=10;state.phase='spectator';resumeSpectating();return;}if(action==='next-team'){spectatorTeam=spectatorTeam%3+1;return;}if(action==='finish-match'){finishMatch(state.match,'Match concluded after surviving crews returned.');debrief();return;}if(action==='start'){start();return;}if(action==='skip'){beginAssembly();return;}if(action==='resume'){resume();return;}if(action==='pause'){pause();return;}if(action==='planner'){menus.hidden=true;hud.hidden=true;unlock();api.missionControl.open();return;}if(b.dataset.screen){if(b.dataset.screen==='settings'||b.dataset.screen==='controls')previousScreen=screen||'home';screen=b.dataset.screen;if(screen==='select')state.mode='select';if(screen==='home')state.mode='menu';renderMenu();}});
cinematic.addEventListener('click',event=>{if(event.target.closest('[data-action="skip"]')){if(state.mode==='launch')finishLaunch();else beginAssembly();}});hud.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;if(b.dataset.playRole!==undefined)selectRole(Number(b.dataset.playRole));if(b.dataset.skill)skill(b.dataset.skill);if(b.dataset.action==='pause')pause();if(b.dataset.action==='return'){beginReturn();return;}if(b.dataset.action==='telemetry'){telemetry=!telemetry;return;}if(b.dataset.action==='priority'){setBuildPriority(state,b.dataset.mode);return;}if(b.dataset.action==='mission-board'){missionExpanded=!missionExpanded;updateHUD();return;}if(b.dataset.action==='build-assist'&&state.phase==='assembly'&&!state.autoBuild.enabled){state.autoBuild.enabled=true;state.autoBuild.t=0;state.constructionStyle='automatic';announce('Robotic build assistance engaged. Remaining modules will install automatically.');updateHUD();return;}if(b.dataset.action==='next-team'){spectatorTeam=spectatorTeam%3+1;return;}if(b.dataset.action==='fast-spectate'){spectatorSpeed=spectatorSpeed===1?10:1;return;}if(b.dataset.action==='view'){state.views[state.selected]=state.views[state.selected]==='first'?'third':'first';}});
addEventListener('keydown',event=>{if(!active||wasPlanning)return;const k=event.key.toLowerCase();if(['input','select','textarea'].includes(document.activeElement?.tagName?.toLowerCase()))return;if(state.mode==='launch'&&(k==='enter'||k==='escape')){event.preventDefault();finishLaunch();return;}if(state.mode==='cutscene'&&(k==='enter'||k==='escape')){event.preventDefault();beginAssembly();return;}if(k==='escape'){event.preventDefault();if(screen==='pause')resume();else if(state.mode==='play')pause();return;}if(state.mode!=='play'||state.paused||screen)return;if([' ','tab','arrowup','arrowdown'].includes(k))event.preventDefault();if(event.repeat)return;keys.add(k);if(k===' '&&state.phase!=='flight')world.actors[state.selected].jumpRequest=true;if('1234'.includes(k)){if(fpsOn()){if(k<'4')fpsSwitch(Number(k)-1);}else selectRole(Number(k)-1);}if(/^f[1-4]$/.test(k)&&fpsOn()){event.preventDefault();selectRole(Number(k[1])-1);}if(k==='v'){state.views[state.selected]=state.views[state.selected]==='first'?'third':'first';announce(state.views[state.selected].toUpperCase()+' PERSON / '+SPECIALISTS[state.selected].name);}if(k==='e'){if(getPreferences().holdToggle)workToggle=!workToggle;interact();}if(k==='k')flightRepair();if(k==='b')focusObjective();if(k==='j'){missionExpanded=!missionExpanded;updateHUD();}if(k==='g')dropFlag(state.match,0,state.selected,world.actors[state.selected].group.position.toArray());if(k==='n'&&state.phase==='surface')beginReturn();if(k==='t')telemetry=!telemetry;if(k==='m'){const z=mapv.cycleZoom();announce('MAP ZOOM '+['CLOSE','NORMAL','WIDE'][z]);}if(k==='i')showInset=!showInset;if(k==='x')toggleExterior();if(k==='r'){if(state.carry[state.selected])rotateCarried(state,state.selected);else if(fpsOn())fpsReload();else reloadTimers[state.selected]=1.4;}if(k==='q'||k==='f')skill(k);if(k==='tab')toggleLook();});addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));
